import pathlib,json,hashlib,struct
p=pathlib.Path(__file__).resolve().parent; ep=p.parent.parent; out=ep/'outputs/visual-review-v2'
def dump(n,v): (p/n).write_text(json.dumps(v,ensure_ascii=False,indent=2),encoding='utf-8')
