 dict(scene_id='M003',asset_id='CN-V2-M003',question='입주 날 어떤 기존 교통을 쓰나?',sequence=['원흥 3호선 강조','새절/DMC 연결 강조','행신/대곡 연결 강조','입주 lane→철도 lane 대비'],camera='고정; zoom/팬 없음',trigger='대본 v2 실제 문장 확정 후 매핑',guardrails=['정밀 역핀 없음','서울 지선7728을 광역으로 부르지 않음','실측 통근시간 숫자 없음','2030년은 연도 band']),
